/* Demonstration only: vfork() suspends the parent in state D until the child exits.
   usage: vf SECONDS */
int main(int argc, char **argv) {
    int secs = argc > 1 ? atoi(argv[1]) : 6;
    pid_t pid = vfork();
    if (pid == 0) { sleep(secs); _exit(0); }
    waitpid(pid, NULL, 0);
    return 0;
}

