int main(void) {
    pid_t pid = fork();
    if (pid == 0) {
        _exit(7);                 /* child exits immediately */
    }
    printf("parent pid=%d child pid=%d (child exits, parent does not call wait)\n",
           getpid(), pid);
    fflush(stdout);
    sleep(30);                    /* parent idles without reaping */
    int status;
    waitpid(pid, &status, 0);     /* reap: the zombie disappears */
    printf("reaped: exit status %d\n", WEXITSTATUS(status));
    return 0;
}

