static long minflt(void) { struct rusage r; getrusage(RUSAGE_SELF, &r); return r.ru_minflt; }

static void show(const char *who) {
    char cmd[128];
    snprintf(cmd, sizeof cmd,
             "grep -E '^(Rss|Pss|Private_Dirty|Shared_Dirty):' /proc/%d/smaps_rollup"
             " | tr -s ' ' | tr '\\n' ' '", getpid());
    printf("%-22s", who); fflush(stdout);
    if (system(cmd) != 0) return;
    printf("\n");
}

int main(void) {
    char *buf = malloc(SIZE);
    memset(buf, 1, SIZE);                       /* parent touches all 16384 pages */
    show("parent before fork:");
    pid_t pid = fork();
    if (pid == 0) {
        long f0 = minflt();
        long sum = 0;
        for (long i = 0; i < SIZE; i += 4096) sum += buf[i];   /* read only */
        printf("child read  : %ld minor faults\n", minflt() - f0);
        f0 = minflt();
        for (long i = 0; i < SIZE / 2; i += 4096) buf[i] = 2;  /* write half the pages */
        printf("child write : %ld minor faults (8192 pages written)\n", minflt() - f0);
        show("child after writes:");
        printf("child sees buf[0]=%d, sum=%ld\n", buf[0], sum);
        _exit(0);
    }
    waitpid(pid, NULL, 0);
    printf("parent sees buf[0]=%d (unchanged)\n", buf[0]);
    return 0;
}

