/* Bounded fork loop: tries to create up to 100 children that sleep for 3 seconds. */
int main(void) {
    int ok = 0;
    for (int i = 0; i < 100; i++) {
        pid_t pid = fork();
        if (pid == 0) { sleep(3); _exit(0); }
        if (pid < 0) {
            printf("fork #%d failed: errno=%d (%s)\n", i + 1, errno, strerror(errno));
            break;
        }
        ok++;
    }
    printf("children created: %d\n", ok);
    while (wait(NULL) > 0) { }
    return 0;
}

