static int shared = 0;                    /* one variable, one address space */

static void *worker(void *arg) {
    shared += 10;
    printf("worker : getpid()=%d gettid()=%ld shared=%d stack var at %p\n",
           getpid(), syscall(SYS_gettid), shared, (void *)&arg);
    fflush(stdout);
    sleep(3);
    return NULL;
}

int main(void) {
    pthread_t t;
    int local = 0;
    printf("main   : getpid()=%d gettid()=%ld stack var at %p\n",
           getpid(), syscall(SYS_gettid), (void *)&local);
    fflush(stdout);
    pthread_create(&t, NULL, worker, NULL);
    sleep(1);
    printf("main   : /proc/%d/task contains:", getpid());
    char cmd[64];
    snprintf(cmd, sizeof cmd, "ls /proc/%d/task | tr '\\n' ' '", getpid());
    fflush(stdout);
    int rc = system(cmd); (void)rc;
    printf("\nmain   : shared=%d after worker ran\n", shared);
    pthread_join(t, NULL);
    return 0;
}

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.Executors;
import java.util.stream.IntStream;

public class ThreadMap {
    static int nativeThreads() throws Exception {
        try (var s = Files.list(Path.of("/proc/self/task"))) { return (int) s.count(); }
    }

    public static void main(String[] args) throws Exception {
        System.out.println("pid " + ProcessHandle.current().pid()
            + ", native threads at start: " + nativeThreads());
        CountDownLatch release = new CountDownLatch(1);
        for (int i = 0; i < 5; i++) {
            Thread.ofPlatform().name("worker-" + i).start(() -> {
                try { release.await(); } catch (InterruptedException e) { }
            });
        }
        System.out.println("after 5 platform threads    : " + nativeThreads());
        try (var exec = Executors.newVirtualThreadPerTaskExecutor()) {
            IntStream.range(0, 10_000).forEach(i -> exec.submit(() -> {
                try { release.await(); } catch (InterruptedException e) { }
                return i;
            }));
            Thread.sleep(500);
            System.out.println("after 10000 virtual threads : " + nativeThreads());
            try (var s = Files.list(Path.of("/proc/self/task"))) {
                s.map(p -> { try { return Files.readString(p.resolve("comm")).trim(); }
                             catch (Exception e) { return "?"; } })
                 .sorted().forEach(n -> System.out.print(n + "  "));
            }
            System.out.println();
            release.countDown();
        }
    }
}

