#define _GNU_SOURCE
#include <pthread.h>
#include <sched.h>
#include <stdio.h>
#include <time.h>
#include <unistd.h>

#define ROUNDS 200000
static int ab[2], ba[2];

static void pin(void) {
    cpu_set_t set; CPU_ZERO(&set); CPU_SET(0, &set);
    sched_setaffinity(0, sizeof set, &set);      /* 0 = calling thread */
}
static double now(void) {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec * 1e9 + ts.tv_nsec;
}
static void *echo(void *arg) {
    pin(); char c;
    for (int i = 0; i < ROUNDS; i++) { read(ab[0], &c, 1); write(ba[1], &c, 1); }
    return NULL;
}
int main(void) {
    pipe(ab); pipe(ba);
    pthread_t t; pthread_create(&t, NULL, echo, NULL);
    pin(); char c = 'x';
    double t0 = now();
    for (int i = 0; i < ROUNDS; i++) { write(ab[1], &c, 1); read(ba[0], &c, 1); }
    double t1 = now();
    pthread_join(t, NULL);
    /* each round trip = 2 context switches (main -> echo -> main) */
    printf("%d round trips in %.1f ms: %.0f ns per context switch (incl. 2 syscalls)\n",
           ROUNDS, (t1 - t0) / 1e6, (t1 - t0) / ROUNDS / 2);
    return 0;
}

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadPoolExecutor;

public class ThreadBomb {
    public static void main(String[] args) throws Exception {
        // newCachedThreadPool: unbounded thread count, 60 s keep-alive
        ExecutorService pool = Executors.newCachedThreadPool();
        ThreadPoolExecutor tpe = (ThreadPoolExecutor) pool;
        try {
            for (int i = 1; i <= 100_000; i++) {
                pool.submit(() -> {                       // each task blocks on a slow backend
                    try { Thread.sleep(20_000); } catch (InterruptedException e) { }
                });
                if (i % 20 == 0) {
                    System.out.println("submitted " + i + ", pool size " + tpe.getPoolSize());
                }
            }
        } catch (Throwable t) {
            System.out.println("after " + tpe.getPoolSize() + " pool threads: " + t);
        }
        System.exit(0);
    }
}

from collections import deque

def round_robin(procs, q):
    """procs: {name: (arrival, burst)}; returns [(name, start, end)] segments."""
    rem = {p: b for p, (a, b) in procs.items()}
    order = sorted(procs, key=lambda k: procs[k][0])
    t, gantt, queue, admitted = 0, [], deque(), set()

    def admit(upto):                       # arrivals up to time t join the queue first
        for p in order:
            if p not in admitted and procs[p][0] <= upto:
                queue.append(p); admitted.add(p)

    admit(0)
    while queue:
        p = queue.popleft()
        run = min(q, rem[p])
        gantt.append((p, t, t + run)); t += run; rem[p] -= run
        admit(t)                           # newcomers queue before the preempted job
        if rem[p] > 0:
            queue.append(p)
    return gantt

